import { useForm } from 'react-hook-form'

function LoginForm() {
  const { register, handleSubmit, formState: { errors } } = useForm()
  
  const onSubmit = async (data) => {
    try {
      const response = await fetch('/api/login', {
        method: 'POST',
        body: JSON.stringify(data)
      })
      if (!response.ok) throw new Error('Credenciales inválidas')
      // Redirigir al dashboard
    } catch (error) {
      alert(error.message)
    }
  }
  
  return (
    <form onSubmit={handleSubmit(onSubmit)}>
      <input 
        {...register('email', { 
          required: 'Email requerido',
          pattern: { value: /^\\S+@\\S+$/i, message: 'Email inválido' }
        })} 
      />
      {errors.email && <span>{errors.email.message}</span>}
      
      <input 
        type="password"
        {...register('password', { 
          required: 'Password requerido',
          minLength: { value: 8, message: 'Mínimo 8 caracteres' }
        })} 
      />
      {errors.password && <span>{errors.password.message}</span>}
      
      <button type="submit">Iniciar sesión</button>
    </form>
  )
}`})}),n.jsx("h3",{style:{marginTop:"2rem",color:"#667eea"},children:"Ejemplo 2: action (cliente) - Buscar productos locales"}),n.jsx("div",{className:"code-block",children:n.jsx(z,{language:"typescript",code:`// ✅ Caso REAL: Filtrar productos que ya tienes cargados (sin servidor)
import { useActionState } from 'react'

// Productos ya cargados desde la API inicial
const products = [
  { id: 1, name: 'iPhone 15', category: 'electronics', price: 999 },
  { id: 2, name: 'MacBook Pro', category: 'electronics', price: 2499 },
  { id: 3, name: 'Camiseta Nike', category: 'clothing', price: 29 }
]

function searchProducts(prevState, formData) {
  const query = formData.get('search')
  const category = formData.get('category')
  
  // Filtrar en el cliente (datos ya cargados)
  const results = products.filter(p => 
    p.name.toLowerCase().includes(query.toLowerCase()) && 
    (!category || p.category === category)
  )
  
  return { results, count: results.length }
}

function SearchForm() {
  const [state, formAction] = useActionState(searchProducts, { results: [] })
  
  return (
    <div>
      <form action={formAction}>
        <input name="search" placeholder="Buscar productos..." />
        <select name="category">
          <option value="">Todas las categorías</option>
          <option value="electronics">Electrónica</option>
          <option value="clothing">Ropa</option>
        </select>
        <button type="submit">Buscar</button>
      </form>
      
      <p>Encontrados: {state.count} productos</p>
      {state.results.map(p => (
        <div key={p.id}>
          {p.name} - \${p.price}
        </div>
      ))}
    </div>
  )
}`})}),n.jsx("h3",{style:{marginTop:"2rem",color:"#667eea"},children:"Ejemplo 3: action (servidor) - Crear post en blog"}),n.jsx("div",{className:"code-block",children:n.jsx(z,{language:"typescript",code:`// ✅ Caso REAL: Guardar post en base de datos (Next.js)
